#!/usr/bin/env python3
"""Add REAL missing vanilla blocks identified by compare_blocks.py.

Each entry below corresponds to a vanilla block that:
  - exists on minecraft.wiki's Category:Blocks
  - is NOT an April-Fools / Education / removed-legacy / disambiguation page
  - is missing from our repo (src/data/blocks/*.json)

This script writes one JSON file per block with the full schema required by
the site, then appends every new block to src/data/blocks/index.json.
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BLOCKS_DIR = ROOT / "src" / "data" / "blocks"
INDEX = BLOCKS_DIR / "index.json"


def block(**kw):
    """Build a block dict with required defaults."""
    d = dict(
        id=kw["id"],
        nameEn=kw["nameEn"],
        nameFa=kw["nameFa"],
        category=kw["category"],
        icon=kw.get("icon", kw["id"]),
        hardness=kw.get("hardness", 1.0),
        tool=kw.get("tool", "none"),
        stackSize=kw.get("stackSize", 64),
        transparent=kw.get("transparent", False),
        lightLevel=kw.get("lightLevel", 0),
        versions=kw.get("versions", {"java": "1.0+", "bedrock": "1.0+"}),
        description=kw.get("description", ""),
        uses=kw.get("uses", []),
        locations=kw.get("locations", []),
        drops=kw.get("drops", []),
        wikiLink=kw.get("wikiLink", ""),
        intro=kw.get("intro", []),
        behavior=kw.get("behavior", []),
        trivia=kw.get("trivia", []),
        history=kw.get("history", []),
        differences=kw.get("differences", []),
        related=kw.get("related", []),
        extraStats=kw.get("extraStats", {
            "blastResistance": 0, "renewable": True, "flammable": False,
            "luminance": 0, "slipperiness": 0.6, "gravity": False,
            "silktouch": False, "minPickaxe": "none", "burnTime": 0,
        }),
        tips=kw.get("tips", []),
        interactions=kw.get("interactions", []),
        buildingIdeas=kw.get("buildingIdeas", []),
        technical=kw.get("technical", []),
    )
    if "farming" in kw:
        d["farming"] = kw["farming"]
    if "redstone" in kw:
        d["redstone"] = kw["redstone"]
    return d


# ---------------------------------------------------------------------------
# Block data — compact form
# ---------------------------------------------------------------------------

BLOCKS = []

