print(f"[part 5] prepared {len(BLOCKS)} blocks (after technical blocks)")

# ============================================================================
# WRITE BLOCKS TO DISK
# ============================================================================

print(f"\n>> writing {len(BLOCKS)} block JSON files to {BLOCKS_DIR}")
written = 0
skipped = 0
for b in BLOCKS:
    fp = BLOCKS_DIR / f"{b['id']}.json"
    if fp.exists():
        # Don't overwrite existing files (we only add missing).
        skipped += 1
        continue
    fp.write_text(json.dumps(b, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    written += 1
print(f"   wrote {written} new block files; skipped {skipped} already-existing")

# Build a summary for downstream consumers
summary = {
    "added": [b["id"] for b in BLOCKS],
    "added_count": len(BLOCKS),
    "written": written,
    "skipped_existing": skipped,
}
with open("/tmp/added_blocks_summary.json", "w") as f:
    json.dump(summary, f, indent=2, ensure_ascii=False)

print("\n>> done.")
